bif_only_sql:
SELECT GSoffered
FROM schools
WHERE ABS(Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools);

sif_only_sql:
SELECT schools.GSoffered AS grade_span_offered
FROM schools
WHERE ABS(schools.Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools);

bif_sif_sql:
SELECT 100.0 * SUM(CASE WHEN client.gender = 'F' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) AS percentage_of_clients_who_are_women
FROM client JOIN district ON client.district_id = district.district_id
WHERE district.A11 IS NOT NULL AND district.A11 > 10000;

SELECT DISTINCT bond.bond_id AS bond_id, molecule.label AS carcinogenic_status
FROM bond JOIN molecule ON bond.molecule_id = molecule.molecule_id
WHERE bond.bond_type = '#';

SELECT COALESCE(a.element, 'NULL') AS toxicology_element FROM molecule m JOIN atom a ON a.molecule_id = m.molecule_id
WHERE m.label = '+' AND substr(a.atom_id, 7, 1) = '4' AND length(a.atom_id) = 7
GROUP BY COALESCE(a.element, 'NULL');

bif_only_sql:
SELECT 100.0 * (
  SELECT COUNT(DISTINCT molecule_id) FROM bond WHERE bond_type = '#'
) / (
  SELECT COUNT(DISTINCT molecule_id) FROM molecule
) AS percent_of_compounds_that_form_triple_bond;

sif_only_sql:
SELECT 100.0 * COUNT(DISTINCT CASE WHEN bond.bond_type = '#' THEN bond.molecule_id END) / NULLIF(COUNT(DISTINCT molecule.molecule_id), 0) AS percent_compounds_with_triple_bond
FROM molecule
LEFT JOIN bond ON bond.molecule_id = molecule.molecule_id;

bif_sif_sql:
SELECT 100.0 * SUM(CASE WHEN bond.bond_type = '#' THEN 1 ELSE 0 END) / NULLIF(COUNT(*),0) AS percent_triple_connections
FROM connected
LEFT JOIN bond ON connected.bond_id = bond.bond_id;

sif_only_sql:
SELECT SUM(CASE WHEN bond.bond_type = ' = ' THEN 1 ELSE 0 END) * 1.0 / COUNT(bond.bond_id) AS percent
FROM bond
WHERE bond.molecule_id = 'TR047';

bif_sif_sql:
SELECT bond.molecule_id AS molecule_id, bond.bond_id AS bond_id, connected.atom_id AS atom_id
FROM bond JOIN connected ON bond.bond_id = connected.bond_id
WHERE bond.bond_id = 'TR000_1_2' AND connected.atom_id = 'TR000_1';

sif_only_sql:
SELECT molecule.label = '+' AS is_carcinogenic
FROM molecule
WHERE molecule.molecule_id = 'TR124';

bif_sif_sql:
SELECT DISTINCT a.element AS element_code
FROM connected c JOIN atom a ON a.atom_id IN (c.atom_id, c.atom_id2)
WHERE c.bond_id = 'TR001_2_4' AND a.element IS NOT NULL;

SELECT bond.bond_id AS bond_id, connected.atom_id AS atom_id, connected.atom_id2 AS atom_id2
FROM bond JOIN connected ON bond.bond_id = connected.bond_id
WHERE bond.bond_type = '-';

bif_only_sql:
SELECT COUNT(*) AS number_of_elements
FROM (
  SELECT atom_id AS atom FROM connected WHERE bond_id = 'TR001_3_4'
  UNION
  SELECT atom_id2 AS atom FROM connected WHERE bond_id = 'TR001_3_4'
);

sif_only_sql:
SELECT (CASE WHEN connected.atom_id IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN connected.atom_id2 IS NOT NULL THEN 1 ELSE 0 END) AS element_count
FROM connected
WHERE connected.bond_id = 'TR001_3_4';

