bif_sif_sql:
SELECT l.name AS league_name
FROM League l JOIN "Match" m ON m.league_id = l.id
WHERE m.season = '2008/2009'
GROUP BY l.id, l.name
HAVING COUNT(*) = (
  SELECT MAX(cnt) FROM (
    SELECT COUNT(*) AS cnt FROM "Match" m2 WHERE m2.season = '2008/2009' GROUP BY m2.league_id
  ) AS sub
);

SELECT CAST(SUM(CASE WHEN p.SEX = 'M' AND l.UA <= 8.0 THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN p.SEX = 'F' AND l.UA <= 6.5 THEN 1 ELSE 0 END), 0) AS male_to_female_ratio
FROM Laboratory l JOIN Patient p ON l.ID = p.ID
WHERE p.SEX IN ('M','F') AND l.UA IS NOT NULL;

SELECT COUNT(*) AS patient_count
FROM Laboratory AS l JOIN Patient AS p ON l.ID = p.ID
WHERE l.CRP = '+' AND p.Description IS NULL;

SELECT DISTINCT Patient.Diagnosis AS Diagnosis
FROM Laboratory JOIN Patient ON Laboratory.ID = Patient.ID
WHERE Laboratory.DNA >= 8 AND Laboratory.DNA IS NOT NULL AND Patient.Diagnosis IS NOT NULL;

bif_only_sql:
SELECT MAX(L.Date)
FROM Laboratory L
WHERE L.ID IN (
  SELECT ID FROM Patient WHERE "First Date" = (SELECT MAX("First Date") FROM Patient)
)
AND L.LDH >= 500;

