SELECT COUNT(*) AS num_normal_TP_tests
FROM Laboratory INNER JOIN Patient ON Laboratory.ID = Patient.ID
WHERE Patient.Diagnosis = 'SJS' AND Laboratory.TP > 6.0 AND Laboratory.TP < 8.5;

SELECT COALESCE(SUM(CASE WHEN substr(event.event_date,1,4) = '2019' THEN budget.spent END), 0) - COALESCE(SUM(CASE WHEN substr(event.event_date,1,4) = '2020' THEN budget.spent END), 0) AS difference_between_total_spent_2019_and_2020
FROM budget JOIN event ON budget.link_to_event = event.event_id
WHERE substr(event.event_date,1,4) IN ('2019','2020') AND budget.spent IS NOT NULL;

