bif_sif_sql:
SELECT c.client_id AS client_id, CAST((strftime('%Y','now') - strftime('%Y', c.birth_date) - (strftime('%m%d','now') < strftime('%m%d', c.birth_date))) AS INTEGER) AS age
FROM client c JOIN disp d ON c.client_id = d.client_id JOIN card ca ON d.disp_id = ca.disp_id
