SELECT (COUNT(CASE WHEN foreign_data.language = 'French' AND (cards.power IS NULL OR cards.power = '*') THEN 1 END) * 100.0) / NULLIF(COUNT(CASE WHEN (cards.power IS NULL OR cards.power = '*') THEN 1 END), 0) AS percentage
FROM cards
JOIN foreign_data ON cards.uuid = foreign_data.uuid;

bif_sif_sql:
SELECT 100.0 * (CAST(COUNT(DISTINCT CASE WHEN (cards.power IS NULL OR cards.power = '*') AND foreign_data.language = 'French' THEN cards.id END) AS REAL) / NULLIF(COUNT(DISTINCT CASE WHEN (cards.power IS NULL OR cards.power = '*') THEN cards.id END), 0)) AS percent_without_power_in_french
FROM cards
LEFT JOIN foreign_data ON foreign_data.uuid = cards.uuid;

SELECT (SUM(CASE WHEN u.DisplayName = 'Mornington' THEN COALESCE(p.ViewCount, 0) ELSE 0 END) - SUM(CASE WHEN u.DisplayName = 'Amos' THEN COALESCE(p.ViewCount, 0) ELSE 0 END)) AS difference_in_view_count
