bif_only_sql:
SELECT AVG(age) AS average_age
FROM (
  SELECT (CAST(strftime('%Y','now') AS INTEGER) - CAST(strftime('%Y', Birthday) AS INTEGER)) AS age
  FROM Patient p
  WHERE SEX = 'M'
    AND EXISTS (
      SELECT 1 FROM Laboratory l
      WHERE l.ID = p.ID AND l."T-CHO" >= 250
    )
);

