FROM superpower
WHERE superpower.power_name = 'Cryokinesis';

bif_sif_sql:
SELECT superpower.id AS power_id
FROM superpower
WHERE superpower.power_name = 'cryokinesis';

SELECT CASE WHEN COUNT(*) = 0 THEN NULL ELSE ROUND(100.0 * SUM(CASE WHEN circuits.country = 'Germany' THEN 1 ELSE 0 END) / COUNT(*), 2) END AS percentage_of_European_Grand_Prix_races_hosted_in_Germany
FROM races JOIN circuits ON races.circuitId = circuits.circuitId
WHERE races.name = 'European Grand Prix';

bif_only_sql:
SELECT surname
FROM drivers
WHERE nationality = 'Italian';

bif_sif_sql:
SELECT drivers.surname AS surname
FROM drivers
WHERE drivers.nationality = 'italian';

SELECT Examination.ANA AS ana_result, Examination.[ANA Pattern] AS ana_pattern
FROM Examination
WHERE Examination.ID = 3605340 AND Examination.[Examination Date] = '1996-12-02';

SELECT DISTINCT p.ID AS patient_id, NULL AS name, p.SEX AS sex, p.Birthday AS date_of_birth
FROM Patient p JOIN Laboratory l ON p.ID = l.ID
WHERE p.Admission = '-' AND l.Date LIKE '1991-10%' AND l.`T-BIL` < 2.0;

sif_only_sql:
SELECT (SUM(CASE WHEN event.type = 'Community Service' THEN 1 ELSE 0 END) * 100.0) / NULLIF(COUNT(event.event_id), 0) AS community_service_percentage
FROM event
WHERE event.event_date BETWEEN '2019-01-01' AND '2019-12-31';
